#!/usr/bin/env python3
"""Patch Windows / Linux runners generated by `flutter create --platforms windows,linux .`:
window title "StreamMKV" and a 1280x760 initial size."""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent

win = root / "windows/runner/main.cpp"
if win.exists():
    s = win.read_text()
    s = s.replace('L"streammkv"', 'L"StreamMKV"')
    s = re.sub(r"Win32Window::Size size\(\d+, \d+\);", "Win32Window::Size size(1280, 760);", s)
    win.write_text(s)
    print("patched", win)

lin = root / "linux/runner/my_application.cc"
if not lin.exists():
    lin = root / "linux/my_application.cc"
if lin.exists():
    s = lin.read_text()
    s = s.replace('"streammkv"', '"StreamMKV"')
    s = re.sub(r"gtk_window_set_default_size\(window, \d+, \d+\);", "gtk_window_set_default_size(window, 1280, 760);", s)
    lin.write_text(s)
    print("patched", lin)

test = root / "test/widget_test.dart"
if test.exists():
    test.unlink()
